    LFRFIDWriteRequest* request = (LFRFIDWriteRequest*)data;
    bool result = false;

    // Fix incorrect length byte
    if(protocol->data[0] != 26 && protocol->data[0] != 50 && protocol->data[0] != 37 &&
       protocol->data[0] != 34 && protocol->data[0] != 36) {
        protocol->data[0] = 26;
